40	pub(super) const NPM_NOT_FOUND_CODE: &str = "E404";
41	
42	/// Only npm's own `E404` code proves absence, never text around it; any other failure is a retried `CommandFailed`.
43	pub(super) fn classify_npm_view(output: &CommandOutput, version: &Version) -> Attempt<ProviderObservationV1> {
44	    if output.success() {
45	        return if output.stdout_trimmed().is_empty() {
46	            transient(ProviderIndeterminateCause::MalformedResponse, None)
47	        } else {
48	            settled(ProviderObservationV1::Exact {
49	                evidence: ProviderEvidenceV1::RegistryVersion {
50	                    version: version.clone(),
51	                    checksum: None,
52	                    yanked: None,
53	                },
54	            })
55	        };
56	    }
57	    let code = if output.stdout_trimmed().is_empty() {
58	        npm_stderr_code(&output.stderr)
59	    } else {
60	        npm_error_code(&output.stdout)
61	    };
62	    if code.as_deref() == Some(NPM_NOT_FOUND_CODE) {
63	        return settled(ProviderObservationV1::Absent);
64	    }
65	    transient(ProviderIndeterminateCause::CommandFailed, None)
66	}
