68	/// The repository URL in `npm view <spec> repository --json`: a string, or an object with a `url`.
69	pub(super) fn npm_view_repository(stdout: &str) -> Option<String> {
70	    let value: serde_json::Value = serde_json::from_str(stdout.trim()).ok()?;
71	    match value {
72	        serde_json::Value::String(url) => Some(url),
73	        serde_json::Value::Object(map) => map.get("url")?.as_str().map(str::to_owned),
74	        _ => None,
75	    }
76	    .filter(|url| !url.is_empty())
77	}
