80	pub(super) fn npm_error_code(stdout: &str) -> Option<String> {
81	    let body: serde_json::Value = serde_json::from_str(stdout.trim()).ok()?;
82	    body.get("error")?.get("code")?.as_str().map(str::to_owned)
83	}
