85	/// The code on npm's `npm ERR! code X` or `npm error code X` stderr line; npm 8 prints no JSON body.
86	pub(super) fn npm_stderr_code(stderr: &str) -> Option<String> {
87	    stderr.lines().find_map(|line| {
88	        let rest = line
89	            .strip_prefix("npm ERR! ")
90	            .or_else(|| line.strip_prefix("npm error "))?;
