106	    fn repository(&self, context: &ProviderContext<'_>, operation: &RegistryPublishOperation) -> Option<String> {
107	        let spec = format!("{}@{}", operation.package_name, operation.version.render());
108	        let mut args = vec!["view", spec.as_str(), "repository", "--json", "--fetch-retries=0"];
109	        if let Some(registry) = operation.registry.endpoint.as_deref() {
110	            args.extend(["--registry", registry]);
111	        }
112	        let workspace_dir = crate::workspace_owner::npm_workspace_dir(context.root(), &operation.package_dir).ok()?;
113	        let output = run_observation(
