130	    /// `npm view` never reads the local package; its cwd is only where the project `.npmrc` supplying the registry is
131	    /// read from. That must be where publishing runs, or the two could address different registries, so it is the
132	    /// workspace that owns the package.
133	    fn observe_once(
134	        &self,
135	        context: &ProviderContext<'_>,
136	        operation: &RegistryPublishOperation,
137	    ) -> Result<Attempt<ProviderObservationV1>, GraphError> {
138	        let spec = format!("{}@{}", operation.package_name, operation.version.render());
139	        // Callisto's bounded retry owns retrying; npm's own fetch retries made an
140	        // unreachable registry take ~70s per attempt.
141	        let mut args = vec!["view", spec.as_str(), "--json", "--fetch-retries=0"];
142	        if let Some(registry) = operation.registry.endpoint.as_deref() {
143	            args.extend(["--registry", registry]);
144	        }
145	        let workspace_dir = crate::workspace_owner::npm_workspace_dir(context.root(), &operation.package_dir)?;
146	        let output = match run_observation(
147	            context.runner(),
148	            programs::NPM,
149	            &args,
150	            &context.root().join(workspace_dir),
151	            timeouts::REGISTRY_QUERY,
152	            true,
153	        )? {
154	            Ok(output) => output,
155	            Err(_unavailable) => return Ok(transient(ProviderIndeterminateCause::CommandFailed, None)),
156	        };
157	        Ok(classify_npm_view(&output, &operation.version))
158	    }
